window.DECK_PY_MODULES = {"filterpy/__init__.py": "", "filterpy/common/__init__.py": "from .helpers import pretty_str\n", "filterpy/common/helpers.py": "# -*- coding: utf-8 -*-\n#pylint: disable=invalid-name\n\n\"\"\"Copyright 2015 Roger R Labbe Jr.\n\nFilterPy library.\n\n\n\nThis is licensed under an MIT license. See the readme.MD file\nfor more information.\n\"\"\"\n\n\nfrom __future__ import print_function\nfrom collections import defaultdict\nimport copy\nimport inspect\nimport numpy as np\n\n\nclass Saver(object):\n    \"\"\"\n    Helper class to save the states of any filter object.\n    Each time you call save() all of the attributes (state, covariances, etc)\n    are appended to lists.\n\n    Generally you would do this once per epoch - predict/update.\n\n    Then, you can access any of the states by using the [] syntax or by\n    using the . operator.\n\n    .. code-block:: Python\n\n        my_saver = Saver()\n        ... do some filtering\n\n        x = my_saver['x']\n        x = my_save.x\n\n    Either returns a list of all of the state `x` values for the entire\n    filtering process.\n\n    If you want to convert all saved lists into numpy arrays, call to_array().\n\n\n    Parameters\n    ----------\n\n    kf : object\n        any object with a __dict__ attribute, but intended to be one of the\n        filtering classes\n\n    save_current : bool, default=True\n        save the current state of `kf` when the object is created;\n\n    skip_private: bool, default=False\n        Control skipping any private attribute (anything starting with '_')\n        Turning this on saves memory, but slows down execution a bit.\n\n    skip_callable: bool, default=False\n        Control skipping any attribute which is a method. Turning this on\n        saves memory, but slows down execution a bit.\n\n    ignore: (str,) tuple of strings\n        list of keys to ignore.\n\n    Examples\n    --------\n\n    .. code-block:: Python\n\n        kf = KalmanFilter(...whatever)\n        # initialize kf here\n\n        saver = Saver(kf) # save data for kf filter\n        for z in zs:\n            kf.predict()\n            kf.update(z)\n            saver.save()\n\n        x = np.array(s.x) # get the kf.x state in an np.array\n        plt.plot(x[:, 0], x[:, 2])\n\n        # ... or ...\n        s.to_array()\n        plt.plot(s.x[:, 0], s.x[:, 2])\n\n    \"\"\"\n\n    def __init__(self, kf, save_current=False,\n                 skip_private=False,\n                 skip_callable=False,\n                 ignore=()):\n        \"\"\" Construct the save object, optionally saving the current\n        state of the filter\"\"\"\n        #pylint: disable=too-many-arguments\n\n        self._kf = kf\n        self._DL = defaultdict(list)\n        self._skip_private = skip_private\n        self._skip_callable = skip_callable\n        self._ignore = ignore\n        self._len = 0\n\n        # need to save all properties since it is possible that the property\n        # is computed only on access. I use this trick a lot to minimize\n        # computing unused information.\n        self.properties = inspect.getmembers(\n            type(kf), lambda o: isinstance(o, property))\n\n        if save_current:\n            self.save()\n\n    def save(self):\n        \"\"\" save the current state of the Kalman filter\"\"\"\n\n        kf = self._kf\n\n        # force all attributes to be computed. this is only necessary\n        # if the class uses properties that compute data only when\n        # accessed\n        for prop in self.properties:\n            self._DL[prop[0]].append(getattr(kf, prop[0]))\n\n        v = copy.deepcopy(kf.__dict__)\n\n        if self._skip_private:\n            for key in list(v.keys()):\n                if key.startswith('_'):\n                    print('deleting', key)\n                    del v[key]\n\n        if self._skip_callable:\n            for key in list(v.keys()):\n                if callable(v[key]):\n                    del v[key]\n\n        for ig in self._ignore:\n            if ig in v:\n                del v[ig]\n\n        for key in list(v.keys()):\n            self._DL[key].append(v[key])\n\n        self.__dict__.update(self._DL)\n        self._len += 1\n\n    def __getitem__(self, key):\n        return self._DL[key]\n\n    def __len__(self):\n        return self._len\n\n    @property\n    def keys(self):\n        \"\"\" list of all keys\"\"\"\n        return list(self._DL.keys())\n\n    def to_array(self):\n        \"\"\"\n        Convert all saved attributes from a list to np.array.\n\n        This may or may not work - every saved attribute must have the\n        same shape for every instance. i.e., if `K` changes shape due to `z`\n        changing shape then the call will raise an exception.\n\n        This can also happen if the default initialization in __init__ gives\n        the variable a different shape then it becomes after a predict/update\n        cycle.\n        \"\"\"\n        for key in self.keys:\n            try:\n                self.__dict__[key] = np.array(self._DL[key])\n            except:\n                # get back to lists so we are in a valid state\n                self.__dict__.update(self._DL)\n\n                raise ValueError(\n                    \"could not convert {} into np.array\".format(key))\n\n    def flatten(self):\n        \"\"\"\n        Flattens any np.array of column vectors into 1D arrays. Basically,\n        this makes data readable for humans if you are just inspecting via\n        the REPL. For example, if you have saved a KalmanFilter object with 89\n        epochs, self.x will be shape (89, 9, 1) (for example). After flatten\n        is run, self.x.shape == (89, 9), which displays nicely from the REPL.\n\n        There is no way to unflatten, so it's a one way trip.\n        \"\"\"\n\n        for key in self.keys:\n            try:\n                arr = self.__dict__[key]\n                shape = arr.shape\n                if shape[2] == 1:\n                    self.__dict__[key] = arr.reshape(shape[0], shape[1])\n            except:\n                # not an ndarray or not a column vector\n                pass\n\n    def __repr__(self):\n        return '<Saver object at {}\\n  Keys: {}>'.format(\n            hex(id(self)), ' '.join(self.keys))\n\n\ndef runge_kutta4(y, x, dx, f):\n    \"\"\"computes 4th order Runge-Kutta for dy/dx.\n\n    Parameters\n    ----------\n\n    y : scalar\n        Initial/current value for y\n    x : scalar\n        Initial/current value for x\n    dx : scalar\n        difference in x (e.g. the time step)\n    f : ufunc(y,x)\n        Callable function (y, x) that you supply to compute dy/dx for\n        the specified values.\n\n    \"\"\"\n\n    k1 = dx * f(y, x)\n    k2 = dx * f(y + 0.5*k1, x + 0.5*dx)\n    k3 = dx * f(y + 0.5*k2, x + 0.5*dx)\n    k4 = dx * f(y + k3, x + dx)\n\n    return y + (k1 + 2*k2 + 2*k3 + k4) / 6.\n\n\ndef pretty_str(label, arr):\n    \"\"\"\n    Generates a pretty printed NumPy array with an assignment. Optionally\n    transposes column vectors so they are drawn on one line. Strictly speaking\n    arr can be any time convertible by `str(arr)`, but the output may not\n    be what you want if the type of the variable is not a scalar or an\n    ndarray.\n\n    Examples\n    --------\n    >>> pprint('cov', np.array([[4., .1], [.1, 5]]))\n    cov = [[4.  0.1]\n           [0.1 5. ]]\n\n    >>> print(pretty_str('x', np.array([[1], [2], [3]])))\n    x = [[1 2 3]].T\n    \"\"\"\n\n    def is_col(a):\n        \"\"\" return true if a is a column vector\"\"\"\n        try:\n            return a.shape[0] > 1 and a.shape[1] == 1\n        except (AttributeError, IndexError):\n            return False\n\n    if label is None:\n        label = ''\n\n    if label:\n        label += ' = '\n\n    if is_col(arr):\n        return label + str(arr.T).replace('\\n', '') + '.T'\n\n    rows = str(arr).split('\\n')\n    if not rows:\n        return ''\n\n    s = label + rows[0]\n    pad = ' ' * len(label)\n    for line in rows[1:]:\n        s = s + '\\n' + pad + line\n\n    return s\n\n\ndef pprint(label, arr, **kwargs):\n    \"\"\" pretty prints an NumPy array using the function pretty_str. Keyword\n    arguments are passed to the print() function.\n\n    See Also\n    --------\n    pretty_str\n\n    Examples\n    --------\n    >>> pprint('cov', np.array([[4., .1], [.1, 5]]))\n    cov = [[4.  0.1]\n           [0.1 5. ]]\n    \"\"\"\n\n    print(pretty_str(label, arr), **kwargs)\n\n\ndef reshape_z(z, dim_z, ndim):\n    \"\"\" ensure z is a (dim_z, 1) shaped vector\"\"\"\n\n    z = np.atleast_2d(z)\n    if z.shape[1] == dim_z:\n        z = z.T\n\n    if z.shape != (dim_z, 1):\n        raise ValueError('z must be convertible to shape ({}, 1)'.format(dim_z))\n\n    if ndim == 1:\n        z = z[:, 0]\n\n    if ndim == 0:\n        z = z[0, 0]\n\n    return z\n\n\ndef inv_diagonal(S):\n    \"\"\"\n    Computes the inverse of a diagonal NxN np.array S. In general this will\n    be much faster than calling np.linalg.inv().\n\n    However, does NOT check if the off diagonal elements are non-zero. So long\n    as S is truly diagonal, the output is identical to np.linalg.inv().\n\n    Parameters\n    ----------\n    S : np.array\n        diagonal NxN array to take inverse of\n\n    Returns\n    -------\n    S_inv : np.array\n        inverse of S\n\n\n    Examples\n    --------\n\n    This is meant to be used as a replacement inverse function for\n    the KalmanFilter class when you know the system covariance S is\n    diagonal. It just makes the filter run faster, there is\n\n    >>> kf = KalmanFilter(dim_x=3, dim_z=1)\n    >>> kf.inv = inv_diagonal  # S is 1x1, so safely diagonal\n    \"\"\"\n\n    S = np.asarray(S)\n\n    if S.ndim != 2 or S.shape[0] != S.shape[1]:\n        raise ValueError('S must be a square Matrix')\n\n    si = np.zeros(S.shape)\n    for i in range(len(S)):\n        si[i, i] = 1. / S[i, i]\n    return si\n\n\ndef outer_product_sum(A, B=None):\n    \"\"\"\n    Computes the sum of the outer products of the rows in A and B\n\n        P = \\Sum {A[i] B[i].T} for i in 0..N\n\n        Notionally:\n\n        P = 0\n        for y in A:\n            P += np.outer(y, y)\n\n    This is a standard computation for sigma points used in the UKF, ensemble\n    Kalman filter, etc., where A would be the residual of the sigma points\n    and the filter's state or measurement.\n\n    The computation is vectorized, so it is much faster than the for loop\n    for large A.\n\n    Parameters\n    ----------\n    A : np.array, shape (M, N)\n        rows of N-vectors to have the outer product summed\n\n    B : np.array, shape (M, N)\n        rows of N-vectors to have the outer product summed\n        If it is `None`, it is set to A.\n\n    Returns\n    -------\n    P : np.array, shape(N, N)\n        sum of the outer product of the rows of A and B\n\n    Examples\n    --------\n\n    Here sigmas is of shape (M, N), and x is of shape (N). The two sets of\n    code compute the same thing.\n\n    >>> P = outer_product_sum(sigmas - x)\n    >>>\n    >>> P = 0\n    >>> for s in sigmas:\n    >>>     y = s - x\n    >>>     P += np.outer(y, y)\n    \"\"\"\n\n    if B is None:\n        B = A\n\n    outer = np.einsum('ij,ik->ijk', A, B)\n    return np.sum(outer, axis=0)\n", "filterpy/gh/__init__.py": "# -*- coding: utf-8 -*-\n\"\"\"Copyright 2015 Roger R Labbe Jr.\n\nFilterPy library.\n\n\n\nThis is licensed under an MIT license. See the readme.MD file\nfor more information.\n\"\"\"\n\n#pylint: disable=wildcard-import\n\nfrom __future__ import absolute_import\n\n__all__ = [\"gh_filter\"]\n\nfrom .gh_filter import *\n", "filterpy/gh/gh_filter.py": "# -*- coding: utf-8 -*-\n# pylint: disable=C0103, R0913, R0902, C0326, R0903, W1401, too-many-lines\n# disable snake_case warning, too many arguments, too many attributes,\n# one space before assignment, too few public methods, anomalous backslash\n# in string\n\n\"\"\"Copyright 2015 Roger R Labbe Jr.\n\nFilterPy library.\n\n\n\nThis is licensed under an MIT license. See the readme.MD file\nfor more information.\n\"\"\"\n\n\nfrom __future__ import (absolute_import, division, print_function,\n                        unicode_literals)\n\nimport numpy as np\nfrom numpy import dot\nfrom filterpy.common import pretty_str\n\n\nclass GHFilterOrder(object):\n    \"\"\" A g-h filter of aspecified order 0, 1, or 2.\n\n    Strictly speaking, the g-h filter is order 1, and the 2nd order\n    filter is called the g-h-k filter. I'm not aware of any filter name\n    that encompasses orders 0, 1, and 2 under one name, or I would use it.\n\n\n    Parameters\n    ----------\n\n    x0 : 1D np.array or scalar\n        Initial value for the filter state. Each value can be a scalar\n        or a np.array.\n\n        You can use a scalar for x0. If order > 0, then 0.0 is assumed\n        for the higher order terms.\n\n        x[0] is the value being tracked\n        x[1] is the first derivative (for order 1 and 2 filters)\n        x[2] is the second derivative (for order 2 filters)\n\n    dt : scalar\n        timestep\n\n    order : int\n        order of the filter. Defines the order of the system\n        0 - assumes system of form x = a_0 + a_1*t\n        1 - assumes system of form x = a_0 +a_1*t + a_2*t^2\n        2 - assumes system of form x = a_0 +a_1*t + a_2*t^2 + a_3*t^3\n\n    g : float\n        filter g gain parameter.\n\n    h : float, optional\n        filter h gain parameter, order 1 and 2 only\n\n    k : float, optional\n        filter k gain parameter, order 2 only\n\n    Atrributes\n    -------\n\n    x : np.array\n        State of the filter.\n\n        x[0] is the value being tracked\n        x[1] is the derivative of x[0] (order 1 and 2 only)\n        x[2] is the 2nd derivative of x[0] (order 2 only)\n\n        This is always an np.array, even for order 0 where you can\n        initialize x0 with a scalar.\n\n    y : np.array\n        Residual - difference between the measurement and the prediction\n\n    dt : scalar\n        timestep\n\n    order : int\n        order of the filter. Defines the order of the system\n        0 - assumes system of form x = a_0 + a_1*t\n        1 - assumes system of form x = a_0 +a_1*t + a_2*t^2\n        2 - assumes system of form x = a_0 +a_1*t + a_2*t^2 + a_3*t^3\n\n    g : float\n        filter g gain parameter.\n\n    h : float\n        filter h gain parameter, order 1 and 2 only\n\n    k : float\n        filter k gain parameter, order 2 only\n\n    z : 1D np.array or scalar\n        measurement passed into update()\n\n    \"\"\"\n\n\n    def __init__(self, x0, dt, order, g, h=None, k=None):\n        \"\"\" Creates a g-h filter of order 0, 1, or 2.\n\n        \"\"\"\n\n        if order < 0 or order > 2:\n            raise ValueError('order must be between 0 and 2')\n\n        if np.isscalar(x0):\n            self.x = np.zeros(order+1)\n            self.x[0] = x0\n        else:\n            self.x = np.copy(x0.astype(float))\n\n        self.dt = dt\n        self.order = order\n\n        self.g = g\n        self.h = h\n        self.k = k\n        self.y = np.zeros(len(self.x)) # residual\n        self.z = np.zeros(len(self.x)) # last measurement\n\n\n\n    def update(self, z, g=None, h=None, k=None):\n        \"\"\"\n        Update the filter with measurement z. z must be the same type\n        or treatable as the same type as self.x[0].\n        \"\"\"\n\n        if self.order == 0:\n            if g is None:\n                g = self.g\n            self.y = z - self.x[0]\n            self.x += dot(g, self.y)\n\n        elif self.order == 1:\n            if g is None:\n                g = self.g\n            if h is None:\n                h = self.h\n            x  = self.x[0]\n            dx = self.x[1]\n            dxdt = dot(dx, self.dt)\n\n            self.y = z - (x + dxdt)\n            self.x[0] = x + dxdt + g*self.y\n            self.x[1] = dx       + h*self.y / self.dt\n\n            self.z = z\n\n        else: # order == 2\n            if g is None:\n                g = self.g\n            if h is None:\n                h = self.h\n            if k is None:\n                k = self.k\n\n            x   = self.x[0]\n            dx  = self.x[1]\n            ddx = self.x[2]\n            dxdt = dot(dx, self.dt)\n            T2 = self.dt**2.\n\n            self.y = z -(x + dxdt +0.5*ddx*T2)\n\n            self.x[0] = x + dxdt + 0.5*ddx*T2 + g*self.y\n            self.x[1] = dx + ddx*self.dt      + h*self.y / self.dt\n            self.x[2] = ddx                 + 2*k*self.y / (self.dt**2)\n\n    def __repr__(self):\n        return '\\n'.join([\n            'GHFilterOrder object',\n            pretty_str('dt', self.dt),\n            pretty_str('order', self.order),\n            pretty_str('x', self.x),\n            pretty_str('g', self.g),\n            pretty_str('h', self.h),\n            pretty_str('k', self.k),\n            pretty_str('y', self.y),\n            pretty_str('z', self.z)\n            ])\n\n\nclass GHFilter(object):\n    \"\"\"\n    Implements the g-h filter. The topic is too large to cover in\n\n    A few basic examples are below, and the tests in ./gh_tests.py may\n    give you more ideas on use.\n\n\n    Parameters\n    ----------\n\n    x : 1D np.array or scalar\n        Initial value for the filter state. Each value can be a scalar\n        or a np.array.\n\n        You can use a scalar for x0. If order > 0, then 0.0 is assumed\n        for the higher order terms.\n\n        x[0] is the value being tracked\n        x[1] is the first derivative (for order 1 and 2 filters)\n        x[2] is the second derivative (for order 2 filters)\n\n    dx : 1D np.array or scalar\n        Initial value for the derivative of the filter state.\n\n    dt : scalar\n        time step\n\n    g : float\n        filter g gain parameter.\n\n    h : float\n        filter h gain parameter.\n\n\n    Attributes\n    ----------\n    x : 1D np.array or scalar\n        filter state\n\n    dx : 1D np.array or scalar\n       derivative of the filter state.\n\n    x_prediction : 1D np.array or scalar\n        predicted filter state\n\n    dx_prediction : 1D np.array or scalar\n       predicted derivative of the filter state.\n\n    dt : scalar\n        time step\n\n    g : float\n        filter g gain parameter.\n\n    h : float\n        filter h gain parameter.\n\n    y : np.array, or scalar\n        residual (difference between measurement and prior)\n\n    z : np.array, or scalar\n        measurement passed into update()\n\n    Examples\n    --------\n\n    Create a basic filter for a scalar value with g=.8, h=.2.\n    Initialize to 0, with a derivative(velocity) of 0.\n\n    >>> from filterpy.gh import GHFilter\n    >>> f = GHFilter (x=0., dx=0., dt=1., g=.8, h=.2)\n\n    Incorporate the measurement of 1\n\n    >>> f.update(z=1)\n    (0.8, 0.2)\n\n    Incorporate a measurement of 2 with g=1 and h=0.01\n\n    >>> f.update(z=2, g=1, h=0.01)\n    (2.0, 0.21000000000000002)\n\n    Create a filter with two independent variables.\n\n    >>> from numpy import array\n    >>> f = GHFilter (x=array([0,1]), dx=array([0,0]), dt=1, g=.8, h=.02)\n\n    and update with the measurements (2,4)\n\n    >>> f.update(array([2,4])\n    (array([ 1.6,  3.4]), array([ 0.04,  0.06]))\n\n\n    References\n    ----------\n\n\n    Sons, 1998.\n\n    \"\"\"\n\n\n    def __init__(self, x, dx, dt, g, h):\n        self.x = x\n        self.dx = dx\n        self.dt = dt\n        self.g = g\n        self.h = h\n        self.dx_prediction = self.dx\n        self.x_prediction  = self.x\n\n        if np.ndim(x) == 0:\n            self.y = 0.   # residual\n            self.z = 0.\n        else:\n            self.y = np.zeros(len(x))\n            self.z = np.zeros(len(x))\n\n\n    def update(self, z, g=None, h=None):\n        \"\"\"\n        performs the g-h filter predict and update step on the\n        measurement z. Modifies the member variables listed below,\n        and returns the state of x and dx as a tuple as a convienence.\n\n        **Modified Members**\n\n        x\n            filtered state variable\n\n        dx\n            derivative (velocity) of x\n\n        residual\n            difference between the measurement and the prediction for x\n\n        x_prediction\n            predicted value of x before incorporating the measurement z.\n\n        dx_prediction\n            predicted value of the derivative of x before incorporating the\n            measurement z.\n\n        Parameters\n        ----------\n\n        z : any\n            the measurement\n        g : scalar (optional)\n            Override the fixed self.g value for this update\n        h : scalar (optional)\n            Override the fixed self.h value for this update\n\n        Returns\n        -------\n\n        x filter output for x\n        dx filter output for dx (derivative of x\n        \"\"\"\n\n        if g is None:\n            g = self.g\n        if h is None:\n            h = self.h\n\n        #prediction step\n        self.dx_prediction = self.dx\n        self.x_prediction  = self.x + (self.dx*self.dt)\n\n        # update step\n        self.y = z - self.x_prediction\n        self.dx = self.dx_prediction + h * self.y / self.dt\n        self.x  = self.x_prediction  + g * self.y\n\n        return (self.x, self.dx)\n\n\n    def batch_filter(self, data, save_predictions=False, saver=None):\n        \"\"\"\n        Given a sequenced list of data, performs g-h filter\n        with a fixed g and h. See update() if you need to vary g and/or h.\n\n        Uses self.x and self.dx to initialize the filter, but DOES NOT\n        alter self.x and self.dx during execution, allowing you to use this\n        class multiple times without reseting self.x and self.dx. I'm not sure\n        how often you would need to do that, but the capability is there.\n        More exactly, none of the class member variables are modified\n        by this function, in distinct contrast to update(), which changes\n        most of them.\n\n        Parameters\n        ----------\n\n        data : list like\n            contains the data to be filtered.\n\n        save_predictions : boolean\n            the predictions will be saved and returned if this is true\n\n        saver : filterpy.common.Saver, optional\n            filterpy.common.Saver object. If provided, saver.save() will be\n            called after every epoch\n\n\n        Returns\n        -------\n\n        results : np.array shape (n+1, 2), where n=len(data)\n           contains the results of the filter, where\n           results[i,0] is x , and\n           results[i,1] is dx (derivative of x)\n           First entry is the initial values of x and dx as set by __init__.\n\n        predictions : np.array shape(n), optional\n           the predictions for each step in the filter. Only retured if\n           save_predictions == True\n        \"\"\"\n\n        x = self.x\n        dx = self.dx\n        n = len(data)\n\n        results = np.zeros((n+1, 2))\n        results[0, 0] = x\n        results[0, 1] = dx\n\n        if save_predictions:\n            predictions = np.zeros(n)\n\n        # optimization to avoid n computations of h / dt\n        h_dt = self.h / self.dt\n\n        for i, z in enumerate(data):\n            #prediction step\n            x_est = x + (dx * self.dt)\n\n            # update step\n            residual = z - x_est\n            dx = dx    + h_dt   * residual # i.e. dx = dx + h * residual / dt\n            x  = x_est + self.g * residual\n\n            results[i+1, 0] = x\n            results[i+1, 1] = dx\n            if save_predictions:\n                predictions[i] = x_est\n\n            if saver is not None:\n                saver.save()\n\n        if save_predictions:\n            return results, predictions\n\n        return results\n\n\n    def VRF_prediction(self):\n        \"\"\"\n        Returns the Variance Reduction Factor of the prediction\n        step of the filter. The VRF is the\n        normalized variance for the filter, as given in the equation below.\n\n        .. math::\n            VRF(\\hat{x}_{n+1,n}) = \\\\frac{VAR(\\hat{x}_{n+1,n})}{\\sigma^2_x}\n\n        References\n        ----------\n\n        Asquith, \"Weight Selection in First Order Linear Filters\"\n        Report No RG-TR-69-12, U.S. Army Missle Command. Redstone Arsenal, Al.\n        November 24, 1970.\n        \"\"\"\n\n        g = self.g\n        h = self.h\n\n        return (2*g**2 + 2*h + g*h) / (g*(4 - 2*g - h))\n\n\n    def VRF(self):\n        \"\"\"\n        Returns the Variance Reduction Factor (VRF) of the state variable\n        of the filter (x) and its derivatives (dx, ddx). The VRF is the\n        normalized variance for the filter, as given in the equations below.\n\n        .. math::\n            VRF(\\hat{x}_{n,n}) = \\\\frac{VAR(\\hat{x}_{n,n})}{\\sigma^2_x}\n\n            VRF(\\hat{\\dot{x}}_{n,n}) = \\\\frac{VAR(\\hat{\\dot{x}}_{n,n})}{\\sigma^2_x}\n\n            VRF(\\hat{\\ddot{x}}_{n,n}) = \\\\frac{VAR(\\hat{\\ddot{x}}_{n,n})}{\\sigma^2_x}\n\n        Returns\n        -------\n\n        vrf_x   VRF of x state variable\n        vrf_dx  VRF of the dx state variable (derivative of x)\n        \"\"\"\n\n        g = self.g\n        h = self.h\n\n        den = g*(4 - 2*g - h)\n\n        vx = (2*g**2 + 2*h - 3*g*h) / den\n        vdx = 2*h**2 / (self.dt**2 * den)\n\n        return (vx, vdx)\n\n    def __repr__(self):\n        return '\\n'.join([\n            'GHFilter object',\n            pretty_str('dt', self.dt),\n            pretty_str('g', self.g),\n            pretty_str('h', self.h),\n            pretty_str('x', self.x),\n            pretty_str('dx', self.dx),\n            pretty_str('x_prediction', self.x_prediction),\n            pretty_str('dx_prediction', self.dx_prediction),\n            pretty_str('y', self.y),\n            pretty_str('z', self.z)\n            ])\n\n\nclass GHKFilter(object):\n    \"\"\"\n    Implements the g-h-k filter.\n\n    Parameters\n    ----------\n\n    x : 1D np.array or scalar\n        Initial value for the filter state. Each value can be a scalar\n        or a np.array.\n\n        You can use a scalar for x0. If order > 0, then 0.0 is assumed\n        for the higher order terms.\n\n        x[0] is the value being tracked\n        x[1] is the first derivative (for order 1 and 2 filters)\n        x[2] is the second derivative (for order 2 filters)\n\n    dx : 1D np.array or scalar\n        Initial value for the derivative of the filter state.\n\n    ddx : 1D np.array or scalar\n        Initial value for the second derivative of the filter state.\n\n    dt : scalar\n        time step\n\n    g : float\n        filter g gain parameter.\n\n    h : float\n        filter h gain parameter.\n\n    k : float\n        filter k gain parameter.\n\n\n\n    Attributes\n    ----------\n    x : 1D np.array or scalar\n        filter state\n\n    dx : 1D np.array or scalar\n       derivative of the filter state.\n\n    ddx : 1D np.array or scalar\n       second derivative of the filter state.\n\n    x_prediction : 1D np.array or scalar\n        predicted filter state\n\n    dx_prediction : 1D np.array or scalar\n       predicted derivative of the filter state.\n\n    ddx_prediction : 1D np.array or scalar\n       second predicted derivative of the filter state.\n\n    dt : scalar\n        time step\n\n    g : float\n        filter g gain parameter.\n\n    h : float\n        filter h gain parameter.\n\n    k : float\n        filter k gain parameter.\n\n    y : np.array, or scalar\n        residual (difference between measurement and prior)\n\n    z : np.array, or scalar\n        measurement passed into update()\n\n    References\n    ----------\n\n    Sons, 1998.\n    \"\"\"\n\n    def __init__(self, x, dx, ddx, dt, g, h, k):\n        self.x = x\n        self.dx = dx\n        self.ddx = ddx\n        self.x_prediction = self.x\n        self.dx_prediction = self.dx\n        self.ddx_prediction = self.ddx\n\n        self.dt = dt\n        self.g = g\n        self.h = h\n        self.k = k\n\n        if np.ndim(x) == 0:\n            self.y = 0.  # residual\n            self.z = 0.\n        else:\n            self.y = np.zeros(len(x))\n            self.z = np.zeros(len(x))\n\n\n    def update(self, z, g=None, h=None, k=None):\n        \"\"\"\n        Performs the g-h filter predict and update step on the\n        measurement z.\n\n        On return, self.x, self.dx, self.y, and self.x_prediction\n        will have been updated with the results of the computation. For\n        convienence, self.x and self.dx are returned in a tuple.\n\n        Parameters\n        ----------\n\n        z : scalar\n            the measurement\n        g : scalar (optional)\n            Override the fixed self.g value for this update\n        h : scalar (optional)\n            Override the fixed self.h value for this update\n        k : scalar (optional)\n            Override the fixed self.k value for this update\n\n        Returns\n        -------\n\n        x filter output for x\n        dx filter output for dx (derivative of x\n\n        \"\"\"\n\n        if g is None:\n            g = self.g\n        if h is None:\n            h = self.h\n        if k is None:\n            k = self.k\n\n        dt = self.dt\n        dt_sqr = dt**2\n        #prediction step\n        self.ddx_prediction = self.ddx\n        self.dx_prediction  = self.dx + self.ddx*dt\n        self.x_prediction   = self.x  + self.dx*dt + .5*self.ddx*(dt_sqr)\n\n        # update step\n        self.y = z - self.x_prediction\n\n        self.ddx = self.ddx_prediction + 2*k*self.y / dt_sqr\n        self.dx  = self.dx_prediction  + h * self.y / dt\n        self.x   = self.x_prediction   + g * self.y\n\n        return (self.x, self.dx)\n\n\n    def batch_filter(self, data, save_predictions=False):\n        \"\"\"\n        Performs g-h filter with a fixed g and h.\n\n        Uses self.x and self.dx to initialize the filter, but DOES NOT\n        alter self.x and self.dx during execution, allowing you to use this\n        class multiple times without reseting self.x and self.dx. I'm not sure\n        how often you would need to do that, but the capability is there.\n        More exactly, none of the class member variables are modified\n        by this function.\n\n        Parameters\n        ----------\n\n        data : list_like\n            contains the data to be filtered.\n\n        save_predictions : boolean\n            The predictions will be saved and returned if this is true\n\n        Returns\n        -------\n\n        results : np.array shape (n+1, 2), where n=len(data)\n           contains the results of the filter, where\n           results[i,0] is x , and\n           results[i,1] is dx (derivative of x)\n           First entry is the initial values of x and dx as set by __init__.\n\n        predictions : np.array shape(n), or None\n           the predictions for each step in the filter. Only returned if\n           save_predictions == True\n        \"\"\"\n\n        x = self.x\n        dx = self.dx\n        n = len(data)\n\n        results = np.zeros((n+1, 2))\n        results[0, 0] = x\n        results[0, 1] = dx\n\n        if save_predictions:\n            predictions = np.zeros(n)\n\n        # optimization to avoid n computations of h / dt\n        h_dt = self.h / self.dt\n\n        for i, z in enumerate(data):\n            #prediction step\n            x_est = x + (dx*self.dt)\n\n            # update step\n            residual = z - x_est\n            dx = dx    + h_dt   * residual # i.e. dx = dx + h * residual / dt\n            x  = x_est + self.g * residual\n\n            results[i+1, 0] = x\n            results[i+1, 1] = dx\n            if save_predictions:\n                predictions[i] = x_est\n\n        if save_predictions:\n            return results, predictions\n\n        return results\n\n\n    def VRF_prediction(self):\n        \"\"\"\n        Returns the Variance Reduction Factor for x of the prediction\n        step of the filter.\n\n        This implements the equation\n\n        .. math::\n            VRF(\\hat{x}_{n+1,n}) = \\\\frac{VAR(\\hat{x}_{n+1,n})}{\\sigma^2_x}\n\n        References\n        ----------\n\n        Asquith and Woods, \"Total Error Minimization in First\n        and Second Order Prediction Filters\" Report No RE-TR-70-17, U.S.\n        Army Missle Command. Redstone Arsenal, Al. November 24, 1970.\n        \"\"\"\n\n        g = self.g\n        h = self.h\n        k = self.k\n        gh2 = 2*g + h\n        return ((g*k*(gh2-4)+ h*(g*gh2+2*h)) /\n                (2*k - (g*(h+k)*(gh2-4))))\n\n\n    def bias_error(self, dddx):\n        \"\"\"\n        Returns the bias error given the specified constant jerk(dddx)\n\n        Parameters\n        ----------\n\n        dddx : type(self.x)\n            3rd derivative (jerk) of the state variable x.\n\n        References\n        ----------\n\n        Asquith and Woods, \"Total Error Minimization in First\n        and Second Order Prediction Filters\" Report No RE-TR-70-17, U.S.\n        Army Missle Command. Redstone Arsenal, Al. November 24, 1970.\n        \"\"\"\n        return -self.dt**3 * dddx / (2*self.k)\n\n\n    def VRF(self):\n        \"\"\"\n        Returns the Variance Reduction Factor (VRF) of the state variable\n        of the filter (x) and its derivatives (dx, ddx). The VRF is the\n        normalized variance for the filter, as given in the equations below.\n\n        .. math::\n            VRF(\\hat{x}_{n,n}) = \\\\frac{VAR(\\hat{x}_{n,n})}{\\sigma^2_x}\n\n            VRF(\\hat{\\dot{x}}_{n,n}) = \\\\frac{VAR(\\hat{\\dot{x}}_{n,n})}{\\sigma^2_x}\n\n            VRF(\\hat{\\ddot{x}}_{n,n}) = \\\\frac{VAR(\\hat{\\ddot{x}}_{n,n})}{\\sigma^2_x}\n\n        Returns\n        -------\n\n        vrf_x : type(x)\n            VRF of x state variable\n\n        vrf_dx : type(x)\n            VRF of the dx state variable (derivative of x)\n\n        vrf_ddx : type(x)\n            VRF of the ddx state variable (second derivative of x)\n        \"\"\"\n\n        g = self.g\n        h = self.h\n        k = self.k\n\n        # common subexpressions in the equations pulled out for efficiency,\n        # they don't 'mean' anything.\n        hg4 = 4- 2*g - h\n        ghk = g*h + g*k - 2*k\n\n        vx = (2*h*(2*(g**2) + 2*h - 3*g*h) - 2*g*k*hg4) / (2*k - g*(h+k) * hg4)\n        vdx = (2*(h**3) - 4*(h**2)*k + 4*(k**2)*(2-g)) / (2*hg4*ghk)\n        vddx = 8*h*(k**2) / ((self.dt**4)*hg4*ghk)\n\n        return (vx, vdx, vddx)\n\n\n    def __repr__(self):\n        return '\\n'.join([\n            'GHFilter object',\n            pretty_str('dt', self.dt),\n            pretty_str('g', self.g),\n            pretty_str('h', self.h),\n            pretty_str('k', self.k),\n            pretty_str('x', self.x),\n            pretty_str('dx', self.dx),\n            pretty_str('ddx', self.ddx),\n            pretty_str('x_prediction', self.x_prediction),\n            pretty_str('dx_prediction', self.dx_prediction),\n            pretty_str('ddx_prediction', self.dx_prediction),\n            pretty_str('y', self.y),\n            pretty_str('z', self.z)\n            ])\n\n\ndef optimal_noise_smoothing(g):\n    \"\"\" provides g,h,k parameters for optimal smoothing of noise for a given\n    value of g. This is due to Polge and Bhagavan[1].\n\n    Parameters\n    ----------\n\n    g : float\n        value for g for which we will optimize for\n\n    Returns\n    -------\n\n    (g,h,k) : (float, float, float)\n        values for g,h,k that provide optimal smoothing of noise\n\n\n    Examples\n    --------\n\n    .. code-block:: Python\n\n        from filterpy.gh import GHKFilter, optimal_noise_smoothing\n\n        g,h,k = optimal_noise_smoothing(g)\n        f = GHKFilter(0,0,0,1,g,h,k)\n        f.update(1.)\n\n\n    References\n    ----------\n\n    [1] Polge and Bhagavan. \"A Study of the g-h-k Tracking Filter\".\n    Report No. RE-CR-76-1. University of Alabama in Huntsville.\n    July, 1975\n\n    \"\"\"\n\n    h = ((2*g**3 - 4*g**2) + (4*g**6 -64*g**5 + 64*g**4)**.5) / (8*(1-g))\n    k = (h*(2-g) - g**2) / g\n\n    return (g, h, k)\n\n\ndef least_squares_parameters(n):\n    \"\"\" An order 1 least squared filter can be computed by a g-h filter\n    by varying g and h over time according to the formulas below, where\n    the first measurement is at n=0, the second is at n=1, and so on:\n\n    .. math::\n\n        h_n = \\\\frac{6}{(n+2)(n+1)}\n\n        g_n = \\\\frac{2(2n+1)}{(n+2)(n+1)}\n\n    Parameters\n    ----------\n\n    n : int\n        the nth measurement, starting at 0 (i.e. first measurement has n==0)\n\n    Returns\n    -------\n\n    (g,h)  : (float, float)\n        g and h parameters for this time step for the least-squares filter\n\n    Examples\n    --------\n\n    .. code-block:: Python\n\n        from filterpy.gh import GHFilter, least_squares_parameters\n\n        lsf = GHFilter (0, 0, 1, 0, 0)\n        z = 10\n        for i in range(10):\n            g,h = least_squares_parameters(i)\n            lsf.update(z, g, h)\n\n    \"\"\"\n    den = (n+2)*(n+1)\n\n    g = (2*(2*n + 1)) / den\n    h = 6 / den\n    return (g, h)\n\n\ndef critical_damping_parameters(theta, order=2):\n    \"\"\" Computes values for g and h (and k for g-h-k filter) for a\n    critically damped filter.\n\n    The idea here is to create a filter that reduces the influence of\n    old data as new data comes in. This allows the filter to track a\n    moving target better. This goes by different names. It may be called the\n    discounted least-squares g-h filter, a fading-memory polynomal filter\n    of order 1, or a critically damped g-h filter.\n\n    In a normal least-squares filter we compute the error for each point as\n\n    .. math::\n\n        \\epsilon_t = (z-\\\\hat{x})^2\n\n    For a crically damped filter we reduce the influence of each error by\n\n     .. math::\n\n         \\\\theta^{t-i}\n\n    where\n\n     .. math::\n\n         0 <= \\\\theta <= 1\n\n    In other words the last error is scaled by theta, the next to last by\n    theta squared, the next by theta cubed, and so on.\n\n    Parameters\n    ----------\n\n    theta : float, 0 <= theta <= 1\n        scaling factor for previous terms\n\n    order : int, 2 (default) or 3\n       order of filter to create the parameters for. g and h will be\n       calculated for the order 2, and g, h, and k for order 3.\n\n    Returns\n    -------\n    g : scalar\n        optimal value for g in the g-h or g-h-k filter\n\n    h : scalar\n        optimal value for h in the g-h or g-h-k filter\n\n    k : scalar\n        optimal value for g in the g-h-k filter\n\n    Examples\n    --------\n\n    .. code-block:: Python\n\n        from filterpy.gh import GHFilter, critical_damping_parameters\n\n        g,h = critical_damping_parameters(0.3)\n        critical_filter = GHFilter(0, 0, 1, g, h)\n\n    References\n    ----------\n\n    Sons, 1998.\n\n    Polge and Bhagavan. \"A Study of the g-h-k Tracking Filter\".\n    Report No. RE-CR-76-1. University of Alabama in Huntsville.\n    July, 1975\n\n    \"\"\"\n    if theta < 0 or theta > 1:\n        raise ValueError('theta must be between 0 and 1')\n\n    if order == 2:\n        return (1. - theta**2, (1. - theta)**2)\n\n    if order == 3:\n        return (1. - theta**3, 1.5*(1.-theta**2)*(1.-theta), .5*(1 - theta)**3)\n\n    raise ValueError('bad order specified: {}'.format(order))\n\n\ndef benedict_bornder_constants(g, critical=False):\n    \"\"\" Computes the g,h constants for a Benedict-Bordner filter, which\n    minimizes transient errors for a g-h filter.\n\n    Returns the values g,h for a specified g. Strictly speaking, only h\n    is computed, g is returned unchanged.\n\n    The default formula for the Benedict-Bordner allows ringing. We can\n    \"nearly\" critically damp it; ringing will be reduced, but not entirely\n    eliminated at the cost of reduced performance.\n\n    Parameters\n    ----------\n\n    g : float\n        scaling factor g for the filter\n\n    critical : boolean, default False\n        Attempts to critically damp the filter.\n\n    Returns\n    -------\n\n    g : float\n        scaling factor g (same as the g that was passed in)\n\n    h : float\n        scaling factor h that minimizes the transient errors\n\n    Examples\n    --------\n\n    .. code-block:: Python\n\n        from filterpy.gh import GHFilter, benedict_bornder_constants\n        g, h = benedict_bornder_constants(.855)\n        f = GHFilter(0, 0, 1, g, h)\n\n    References\n    ----------\n\n    Sons, 1998.\n\n    \"\"\"\n\n    g_sqr = g**2\n    if critical:\n        return (g, 0.8 * (2. - g_sqr - 2*(1-g_sqr)**.5) / g_sqr)\n\n    return (g, g_sqr / (2.-g))\n", "ipywidgets/__init__.py": "\"\"\"Minimal ipywidgets stand-in for the in-browser deck (Pyodide has no ipywidgets).\n\ninteract() calls the function once with the current slider values and leaves\nthe slider spec in builtins._deck_interact; deck.js draws range inputs from it\nand re-runs the block with builtins._deck_values when a slider is released.\n\"\"\"\nimport builtins\n\n\nclass FloatSlider:\n    def __init__(self, value=0.0, min=0.0, max=10.0, step=0.1, description='', **kwargs):\n        self.value = float(value)\n        self.min = float(min)\n        self.max = float(max)\n        self.step = float(step)\n        self.description = description\n\n\ndef interact(f, **kwargs):\n    values = getattr(builtins, '_deck_values', None) or {}\n    spec, args = {}, {}\n    for name, w in kwargs.items():\n        if isinstance(w, FloatSlider):\n            spec[name] = {'value': w.value, 'min': w.min, 'max': w.max, 'step': w.step}\n            args[name] = float(values.get(name, w.value))\n        else:\n            args[name] = w\n    builtins._deck_interact = spec\n    f(**args)\n    return f\n\n\nif __name__ == '__main__':\n    seen = []\n    builtins._deck_values = {'g': 0.5}\n    interact(lambda x, g: seen.append((x, g)), x=FloatSlider(value=1, min=-2, max=2), g=FloatSlider(value=.1))\n    assert seen == [(1.0, 0.5)], seen\n    assert builtins._deck_interact['x'] == {'value': 1.0, 'min': -2.0, 'max': 2.0, 'step': 0.1}\n    print('ok')\n"};
